"""Source-reviewed chapter 8 answers with exact symbolic verification. Run from repository root."""
import json
from pathlib import Path
import sympy as s
M=s.Matrix
Q={}
def tex(x):
 if isinstance(x,s.MatrixBase): return r'\begin{bmatrix}'+r'\\'.join(' & '.join(s.latex(v) for v in x.row(i)) for i in range(x.rows))+r'\end{bmatrix}'
 return s.latex(x)
def math(x): return r'\('+ (tex(x) if not isinstance(x,str) else x)+r'\)'
def c(label,prompt,answer,wrong,steps):
 assert len(set([answer]+wrong))==len(wrong)+1
 return dict(label=label,selectionPrompt=prompt,type='choice',answer=answer,options=[answer]+wrong,explanation=' '.join(steps),workedSteps=steps)
def n(label,prompt,answer,steps):return dict(label=label,selectionPrompt=prompt,type='numeric',answer=int(answer) if int(answer)==answer else float(answer),tolerance=1e-8,explanation=' '.join(steps),workedSteps=steps)
def mat(label,prompt,A,steps):
 A=M(A); wrong=A.copy();wrong[0,0]+=1; wrong2=-A
 if wrong2==A:wrong2=A+s.ones(*A.shape)
 return c(label,prompt,math(A),[math(wrong),math(wrong2)],steps+[r'The resulting matrix is '+math(A)+'.'])
def add(sec,num,fields,scope=None,notice=None):
 id=f'anton-section-8-{sec}-{num}' if sec else f'anton-chapter-08-supplementary-{num}'
 Q[id]=dict(fields=fields,scope=scope or 'All requested parts; proof and sketch tasks are assessed by specific mathematical choices.',complete=True,sourceImageReviewed=True)
 if notice:Q[id]['reviewNotice']=notice
 Path('scripts/linear-answer-checks/ch08-reviewed.json').write_text(json.dumps(dict(chapter=8,questions=Q),indent=2,ensure_ascii=False)+'\n')
def yn(label,prompt,yes,steps):return c(label,prompt,'Yes' if yes else 'No',['No' if yes else 'Yes'],steps)
def expr(label,prompt,a,b,d,steps):return c(label,prompt,math(a),[math(b),math(d)],steps)
# 8.1: General transformations
add(1,1,[c('a','Is the squaring map linear?','Not linear',['Linear, with zero kernel','Linear, with all matrices in its kernel'],[r'For the identity matrix, \(T(2I)=4I\), whereas \(2T(I)=2I\). Homogeneity fails.']),expr('b','Choose the linearity and kernel description for the trace map.',r'\text{Linear};\ \ker T=\{\begin{bmatrix}a&b\\c&-a\end{bmatrix}:a,b,c\in\mathbb R\}',r'\text{Linear};\ \ker T=\{0\}',r'\text{Not linear}',[r'Trace adds diagonal entries, so \(\operatorname{tr}(\alpha A+\beta B)=\alpha\operatorname{tr}A+\beta\operatorname{tr}B\).',r'The zero-output equation is \(a+d=0\); the off-diagonal entries are free.']),expr('c','Choose the linearity and kernel description for the symmetrization map.',r'\text{Linear};\ \ker T=\{\begin{bmatrix}0&b\\-b&0\end{bmatrix}:b\in\mathbb R\}',r'\text{Linear};\ \ker T=\{\begin{bmatrix}a&b\\b&d\end{bmatrix}\}',r'\text{Not linear}',[r'Transpose respects linear combinations, so \(A\mapsto A+A^T\) is linear.',r'\(A+A^T=0\) gives \(a=d=0\) and \(c=-b\).'])])
