add(0,18,[c('proof','Choose the equivalence proving the assertion.','T injective ⇔ its coordinate matrix has zero nullity ⇔ the square matrix is invertible ⇔ det(T) ≠ 0',['T injective ⇔ its coordinate matrix has determinant 0','T injective ⇔ every matrix entry is nonzero'],[r'Choose a basis in the finite-dimensional space used to define \(\det T\); let \(A=[T]_B\).',r'The coordinate isomorphism identifies \(\ker T\) with \(\ker A\), so T is one-to-one exactly when \(Ax=0\) has only the zero solution.',r'For square A, this is equivalent to invertibility and hence to \(\det A\ne0\). The operator determinant equals \(\det A\), independently of basis.'])])
add(0,19,[expr('a','Identity proving second differentiation is linear',r'D(\alpha f+\beta g)=\alpha f\prime\prime+\beta g\prime\prime=\alpha Df+\beta Dg',r'D(\alpha f+\beta g)=\alpha\beta(f\prime\prime+g\prime\prime)',r'D(fg)=D(f)D(g)',[r'Differentiate a linear combination twice; constant factors pass through each derivative.',r'The resulting equality proves additivity and homogeneity.']),expr('b','Basis for the kernel of D',r'\{1,x\}',r'\{e^x,e^{-x}\}',r'\{x,x^2\}',[r'\(f\prime\prime=0\) implies \(f\prime=b\) and \(f=a+bx\).',r'The functions 1 and x are independent and span all such functions, giving the kernel basis.']),expr('c','Basis and dimension of the solution space D(f)=f',r'\{e^x,e^{-x}\};\quad\dim=2',r'\{\sin x,\cos x\};\quad\dim=2',r'\{1,x\};\quad\dim=2',[r'The equation is \(f\prime\prime-f=0\), with characteristic roots \(1,-1\), so every solution is \(ae^x+be^{-x}\).',r'The solution set is \(\ker(D-I)\), hence a subspace. The two functions are independent: evaluating a zero combination and its derivative at 0 gives \(a+b=a-b=0\).',r'Thus they form a basis and the dimension is 2.'])])
